import{_ as a,C as i,o as e,c as l,a2 as r,b as s,w as d,a as h,E as n,a3 as u}from"./chunks/framework.CWWEQfK7.js";const _=JSON.parse('{"title":"Ershu 是什么","description":"了解 Ershu 怎样把多个代码仓库整理成网页和 AI 编程工具都能使用的项目知识。","frontmatter":{"page_id":"overview-what-is-ershu","title":"Ershu 是什么","description":"了解 Ershu 怎样把多个代码仓库整理成网页和 AI 编程工具都能使用的项目知识。"},"headers":[],"relativePath":"overview/what-is-ershu.md","filePath":"overview/what-is-ershu.md","lastUpdated":1786627803000}'),E={name:"overview/what-is-ershu.md"};function c(A,t,p,P,B,C){const o=i("Mermaid");return e(),l("div",null,[t[1]||(t[1]=r('<h1 id="ershu-是什么" tabindex="-1">Ershu 是什么 <a class="header-anchor" href="#ershu-是什么" aria-label="Permalink to &quot;Ershu 是什么&quot;">​</a></h1><p>Ershu 是一套自行部署的代码理解服务。你把一个产品的前端、后端、微服务和共享库放进同一个项目，Ershu 读取这些仓库，整理出内部 Wiki、代码索引、项目关系和接口约定。</p><p>团队通过网页阅读、搜索和查看关系。AI 编程工具通过 MCP 查询同一份结果。MCP 是一种让 AI 客户端调用外部工具的通用协议，Ershu 提供的是只读查询，不会通过 MCP 修改仓库。</p><h2 id="它与常见做法有什么不同" tabindex="-1">它与常见做法有什么不同 <a class="header-anchor" href="#它与常见做法有什么不同" aria-label="Permalink to &quot;它与常见做法有什么不同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>做法</th><th>擅长什么</th><th>容易缺少什么</th></tr></thead><tbody><tr><td>手写 Wiki</td><td>记录背景、决策和团队经验</td><td>需要持续维护，容易与当前提交脱节</td></tr><tr><td>仓库内搜索</td><td>快速找到已知符号和文字</td><td>很难给出跨仓库项目全貌</td></tr><tr><td>让 AI 直接扫描工作区</td><td>针对当前任务即时读代码</td><td>每次会话都可能重新建立上下文，范围也受当前工作区限制</td></tr><tr><td>Ershu</td><td>保存项目级分析结果，供网页和 MCP 重复使用</td><td>仍需要部署、模型配置和第一次完整分析</td></tr></tbody></table><p>这些做法可以一起使用。手写文档适合记录“为什么”，Ershu 更适合从当前代码整理“现在是什么”。精确行为最终仍由源码和测试决定。</p><h2 id="一次完整分析会留下什么" tabindex="-1">一次完整分析会留下什么 <a class="header-anchor" href="#一次完整分析会留下什么" aria-label="Permalink to &quot;一次完整分析会留下什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结果</th><th>你可以用它做什么</th></tr></thead><tbody><tr><td>项目 Wiki</td><td>按主题阅读模块、流程、配置和仓库说明，并从引用回到源码</td></tr><tr><td>仓库目录与代码索引</td><td>按路径、语言和符号浏览代码，不必先克隆到每位读者的电脑</td></tr><tr><td>关键词与向量索引</td><td>按精确名称或含义搜索代码、文档、接口和配置</td></tr><tr><td>项目知识图谱</td><td>查看仓库、目录、符号、调用和依赖之间的候选关系</td></tr><tr><td>接口约定</td><td>查询公开接口、消费者关系、数据结构和不同版本之间的变化</td></tr><tr><td>运行记录</td><td>查看分析阶段、警告、模型用量、生成结果和失败位置</td></tr></tbody></table><p>文档由模型参与生成。目录、代码索引、接口事实和一部分关系来自确定性分析。Ershu 会在结果中保留提交、新鲜度、来源级别、覆盖范围和截断信息，让调用方知道哪些内容可以直接使用，哪些仍要回到源码确认。</p><h2 id="五个组件怎样配合" tabindex="-1">五个组件怎样配合 <a class="header-anchor" href="#五个组件怎样配合" aria-label="Permalink to &quot;五个组件怎样配合&quot;">​</a></h2>',10)),(e(),s(u,null,{default:d(()=>[n(o,{id:"mermaid-147",class:"ershu-mermaid",graph:"flowchart%20LR%0A%20%20Browser%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%22%5D%20--%3E%20Frontend%5B%22Frontend%22%5D%0A%20%20Frontend%20--%3E%20API%5B%22API%22%5D%0A%20%20Agent%5B%22AI%20%E7%BC%96%E7%A8%8B%E5%B7%A5%E5%85%B7%22%5D%20--%3E%20MCP%5B%22MCP%22%5D%0A%20%20API%20--%3E%20Core%5B%22Core%22%5D%0A%20%20MCP%20--%3E%20Core%0A%20%20Worker%5B%22Worker%22%5D%20--%3E%20Core%0A%20%20API%20--%3E%20Queue%5B(%22PostgreSQL%20%E4%BB%BB%E5%8A%A1%E9%98%9F%E5%88%97%22)%5D%0A%20%20Queue%20--%3E%20Worker%0A%20%20Worker%20--%3E%20Repos%5B%22%E5%8F%AA%E8%AF%BB%E4%BB%93%E5%BA%93%E5%B7%A5%E4%BD%9C%E5%8C%BA%22%5D%0A%20%20Worker%20--%3E%20Knowledge%5B(%22%E6%96%87%E6%A1%A3%E3%80%81%E7%B4%A2%E5%BC%95%E5%92%8C%E5%85%B3%E7%B3%BB%22)%5D%0A%20%20Core%20--%3E%20Knowledge%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[h(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<ul><li><strong>Core</strong> 保存共用的数据、权限、任务状态、查询能力和数据库升级记录。它不是单独的服务。</li><li><strong>API</strong> 为网页提供登录、项目管理、任务、文档、搜索、聊天和后台管理接口。</li><li><strong>Worker</strong> 领取任务，读取仓库并生成文档、索引、关系和接口事实。</li><li><strong>MCP</strong> 把已经保存的项目知识提供给 AI 客户端。</li><li><strong>Frontend</strong> 是团队使用的网页工作区。</li></ul><p>PostgreSQL 保存账号、项目、权限、任务和文档等业务数据。Milvus 保存向量索引。Redis 用于登录限流和轮询协调，不是 Worker 的持久任务队列。</p><h2 id="python-安装可以按组件选择" tabindex="-1">Python 安装可以按组件选择 <a class="header-anchor" href="#python-安装可以按组件选择" aria-label="Permalink to &quot;Python 安装可以按组件选择&quot;">​</a></h2><p><code>ershu</code> 是统一安装入口。默认只安装 Core，需要哪个进程就选择哪个附加项：</p><table tabindex="0"><thead><tr><th>命令</th><th>安装内容</th></tr></thead><tbody><tr><td><code>pip install ershu</code></td><td>Core 和数据库升级命令 <code>ershu-db</code></td></tr><tr><td><code>pip install &quot;ershu[api]&quot;</code></td><td>Core 与 API</td></tr><tr><td><code>pip install &quot;ershu[mcp]&quot;</code></td><td>Core 与 MCP</td></tr><tr><td><code>pip install &quot;ershu[worker]&quot;</code></td><td>Core 与 Worker</td></tr><tr><td><code>pip install &quot;ershu[all]&quot;</code></td><td>Core、API、MCP 与 Worker</td></tr></tbody></table><p>UV 项目可以使用 <code>uv add ershu</code> 或 <code>uv add &quot;ershu[all]&quot;</code>。完整部署还需要 PostgreSQL、Redis、Milvus 等基础设施和单独发布的前端，因此第一次部署更适合直接使用 <code>ershu</code> Release 中的部署压缩包。</p><h2 id="从代码到可用结果" tabindex="-1">从代码到可用结果 <a class="header-anchor" href="#从代码到可用结果" aria-label="Permalink to &quot;从代码到可用结果&quot;">​</a></h2><ol><li>管理员创建账号，配置语言模型和向量模型通道。</li><li>项目负责人创建项目，把属于同一产品的仓库加进来。</li><li>第一次运行覆盖全部活动仓库，建立项目基线。</li><li>Worker 读取仓库，写入 Wiki、索引、关系、契约和运行记录。</li><li>团队在网页使用这些结果，AI 客户端通过 MCP 按需读取。</li><li>代码变化后，通过新运行、计划轮询或签名 Webhook 更新项目事实。</li></ol><p>自动事实刷新不会顺带重写 AI 文档。需要更新文档时，应创建包含文档生成的分析运行。</p><h2 id="使用前先知道这些边界" tabindex="-1">使用前先知道这些边界 <a class="header-anchor" href="#使用前先知道这些边界" aria-label="Permalink to &quot;使用前先知道这些边界&quot;">​</a></h2><ul><li>只有 API 没有 Worker 时，任务可以入队，但不会完成。</li><li>语义搜索需要 Milvus、可用的向量模型通道和已经建好的向量索引。关键词搜索不依赖向量模型。</li><li>关系、影响面和静态运行路径用于缩小候选范围，不等于完整的动态调用证明。</li><li>本地仓库路径必须对实际运行 API、Worker 或 MCP 的主机可见，并进入受信任范围。</li><li>自行部署让团队掌握服务和存储位置。模型服务是否位于内网，仍由部署者的模型通道决定。</li></ul><p>想判断不同角色能得到什么，请看<a href="./use-cases">使用场景</a>。准备动手时，从<a href="/guide/quick-start">单机快速部署</a>开始。</p>',12))])}const k=a(E,[["render",c]]);export{_ as __pageData,k as default};
